package com.pilotapi.integration.openapi;

/**
 * A single difference between the shared OpenAPI specification (expected) and
 * the specification generated by this application (actual).
 */
public record ComplianceFinding(Severity severity, Category category, String location, String message,
                                String expected, String actual) {

    public enum Severity {
        ERROR,
        WARN,
        INFO
    }

    public enum Category {
        PATHS,
        PARAMETERS,
        REQUEST_BODIES,
        RESPONSES,
        SCHEMAS,
        SECURITY,
        METADATA
    }

    @Override
    public String toString() {
        return "[" + severity + "][" + category + "] " + location + ": " + message
            + " (expected: " + expected + ", actual: " + actual + ")";
    }
}
